INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10256107667746, 'strawberry-fermented-yeast-protein-500g-jar', 'Strawberry Fermented Yeast Protein - 500g Jar', 'PRO', 1299.0, 0, 'Fresh, fruity and made with real freeze dried strawberries in every scoop. Enjoy 24g of gut loving protein made using bio fermented yeast protein for easy digestion and muscle support. Now in our upgraded jar with a built in scoop holder for a cleaner experience. 14 servings per jar.');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10161530700066, 'kesar-badam-fermented-yeast-protein-1kg-jar', 'Kesar Badam Fermented Yeast Protein - 1Kg Jar', 'PRO', 2499.0, 0, 'Rich kesar notes, real almond slices, and a flavour that’s been a family favourite for generations. From kulfis to overnight oats, this maaad tasty indulgence now comes with 24g of gut-loving protein and real badam crunch in every scoop. Made with the lightest bio-fermented yeast protein for easy digestion and real muscle support. 28 Servings Per Jar');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10152790655266, '5g-orange-mini-protein-wafer-pack-of-10', '5g Orange Mini Protein Wafer - Pack of 10', 'Wafers mini', 249.0, 0, 'Tastes like sunshine, powers like protein. Zesty orange cream meets light, crunchy wafer layers, made with atta and jowar, 5g protein, no added sugar &amp; no palm oil. Nostalgia, but better or shall we say super! Pack of 10 Protein Wafer Minis');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9980889628962, 'cookies-and-cream-pack-of-20', 'Cookies and Cream Mini - Pack of 20', 'wafers mini', 499.0, 0, 'That childhood treat you loved with a protein upgrade. Layers of creamy vanilla and cocoa come together to give you a bite that’s comforting, heavenly and so damn dreamy');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9840936354082, 'assorted-trial-pack', 'Chocolate & Cold Coffee Assorted - Pack of 8 Sachets', 'PRO', 749.0, 0, 'When you’re making the switch, start smart — try both flavours first. Our Coffee + Chocolate trial pack helps you set your new protein routine. Smoother, lighter, and tastier than anything you’ve had before. Each serving is packed with 24g of gut loving protein that keeps you feeling light. Chocolate - 4 X 36g each Cold Coffee - 4 X 36g each');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10044263039266, 'creatine-monohydrate-unflavoured', 'Creatine Monohydrate 100g - Unflavoured', 'Creatine Monohydrate', 399.0, 0, 'Creatine is one of the most researched supplements in the world for strength and performance . SuperYou Pro Creatine Monohydrate is micronised to 200 mesh for peak absorption and has +1bn CFU probiotic s for easy digestion. Zero calories, zero sugar, zero artificial preservatives . Take one scoop, daily, and you’ll be able to show up stronger and sharper.');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10044260811042, 'creatine-monohydrate-orange', 'Creatine Monohydrate 112g - Orange Kick', 'Creatine Monohydrate', 399.0, 0, 'Creatine is one of the most researched supplements in the world for strength and performance . SuperYou Pro Creatine Monohydrate is micronised to 200 mesh for peak absorption and has +1bn CFU probiotic s for easy digestion. Zero calories, zero sugar, zero artificial preservatives . Take one scoop, daily, and you’ll be able to show up stronger and sharper.');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10044261663010, 'creatine-monohydrate-zesty-lemon', 'Creatine Monohydrate 112g - Zesty Lemon', 'Creatine Monohydrate', 399.0, 0, 'Creatine is one of the most researched supplements in the world for strength and performance . SuperYou Pro Creatine Monohydrate is micronised to 200 mesh for peak absorption and has +1bn CFU probiotic s for easy digestion. Zero calories, zero sugar, zero artificial preservatives . Take one scoop, daily, and you’ll be able to show up stronger and sharper.');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9844890370338, 'unflavoured-1-kg-fermented-yeast-protein', 'Unflavoured Fermented Yeast Protein - 1Kg Jar', 'PRO', 1999.0, 0, 'JUST PROTEIN, Nothing Extra. No flavour, no sweetener, no distractions. Add to anything - your smoothie, oats, or even roti dough, for a clean protein boost that adapts to your day. 30 servings per jar');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10121098199330, 'orange-mini-pack-of-10', '5g Orange Mini Protein Wafer - Pack of 10 X 2', 'Wafers mini', 499.0, 0, 'Tastes like sunshine, powers like protein. Zesty orange cream meets light, crunchy wafer layers, made with atta and jowar, 5g protein, no added sugar &amp; no palm oil. Nostalgia, but better or shall we say super! Pack of 10 X 2 Protein Wafer Minis');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10118903660834, 'cold-coffee-fermented-yeast-protein-pack-of-5', 'Cold Coffee Fermented Yeast Protein - Pack of 5', 'Protein', 449.0, 0, 'Love your brew? This one''s for you. A cold coffee flavour that actually tastes like a frothy coffee with no added sugar, dairy or chalkiness . Each scoop is packed with 24g of gut loving protein that keeps you feeling light. Made with bio-fermented yeast protein for easy digestion and real muscle support. 5 servings');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9487398043938, 'cheese-protein-wafer', 'Cheese Protein Wafer — Pack of 10', 'Wafers', 449.0, 0, 'Pack of 10 protein wafers — Bold, unexpected, unforgettable. This cheese wafer layers sweet and savory flavors between crunchy bites that pack 10g protein, 3g fiber, and zero added sugar. It’s a protein adventure , one bite at a time.');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10021932073250, 'cold-coffee-fermented-yeast-protein-pack-of-5-x-2', 'Cold Coffee Fermented Yeast Protein - Pack of 5 X 2', 'PRO', 749.0, 0, 'Love your brew? This one''s for you. A cold coffee flavour that actually tastes like a frothy coffee with no added sugar, dairy or chalkiness . Each scoop is packed with 24g of gut loving protein that keeps you feeling light. Made with bio-fermented yeast protein for easy digestion and real muscle support. 10 servings');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10102864838946, '20g-mega-protein-wafer-pack-of-6-x-2', '20g Mega Protein Wafer - Pack of 6 X 2', 'Mega Wafer', 1185.0, 0, 'Introducing SuperYou Mega - 20g protein, layered with crispy chocolate wafers, and topped with salted peanuts for extra crunch. Made with atta and jowar, no added sugar, and no palm oil. Whether it’s a long workday, an intense workout, this big boy has got your back. Pack of 6 X 2');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9869869941026, 'mango-hazelnut', 'Mango + Choco Hazelnut', 'wafers mini', 499.0, 0, 'Tropical meets Indulgent. Juicy Mango and rich Choco-Hazelnut, two bold flavours, in one epic box. Fruity or nutty, pick your vibe. Protein Wafer Minis, for when you''re in a mood for a mini snack! Pack of 10 each');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9864493269282, 'choco-hazelnut-and-cookies-cream-pack-of-10-each', 'Mini Choco Hazelnut + Cookies & Cream', 'Wafers mini', 499.0, 0, 'Nutty meets Legendary. Rich choco-hazelnut pairs with cookies &amp; cream for the kind of crunch that feels smooth, creamy, and just the right amount of indulgent. The most iconic combo, now in Protein Wafer Minis. Pack of 10 each');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9864442741026, 'mango-cookies-creme-minis-pack-of-10-each', 'Mango + Cookies & Cream', 'Wafers mini', 499.0, 0, 'Tropical meets Classic. Juicy mango vibes collide with the all-time favourite cookies &amp; cream for a snacking duo that’s indulgent, fresh, and straight-up super. Combo that’s made to win! Pack of 10 each');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9893862801698, 'cookies-cream-protein-wafers-pack-of-10', 'Cookies & Cream Protein Wafers - Pack of 10', 'Wafers', 449.0, 0, 'That childhood treat you loved with a protein upgrade. Layers of creamy vanilla and cocoa come together to give you a bite that’s comforting, heavenly and so damn dreamy. Made with atta and jowar, packed with 10g protein, 3g fiber, no added sugar and no palm oil. Pack of 10 Protein Wafers');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (10021933056290, 'chocolate-cold-coffee-fermented-yeast-protein-pack-of-5-x-2', 'Chocolate & Cold Coffee Fermented Yeast Protein - Pack of 5 x 2', 'PRO', 849.0, 0, 'When you’re making the switch, start smart — try both flavours first. Our Coffee + Chocolate trial pack helps you set your new protein routine. Smoother, lighter, and tastier than anything you’ve had before. Each serving is packed with 24g of gut loving protein that keeps you feeling light. 10 servings');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9841155997986, 'superyou-pro-shaker', 'SuperYou PRO - Shaker', 'Shaker', 499.0, 0, 'Mix, Sip, Repeat! Lightweight, BPA-free, and tough enough for your daily grind. No leaks, no clumps, no stress, just silky smooth shakes every time. Easy to clean, easy to carry, built to move with you.');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9668145316130, 'coffee-protein-wafer-pack-of-10', 'Coffee Protein Wafer - Pack of 10', 'Wafers', 449.0, 0, 'Pack of 10 protein wafers — Smooth like your daily coffee. Crunchy like your favourite snack. 10g protein, no added sugar, no palm oil, and all the drama —because why just sip your coffee when you can bite into it?');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9998885126434, '20g-mega-protein-wafer', '20g Mega Protein Wafer - Pack of 6', 'Mega Wafer', 649.0, 0, 'Introducing SuperYou Mega - 20g protein, layered with crispy chocolate wafers, and topped with salted peanuts for extra crunch. Made with atta and jowar, no added sugar, and no palm oil. Whether it’s a long workday, an intense workout, this big boy has got your back. Pack of 6');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9494053978402, 'variety-box', 'Protein Wafers - Variety Pack of 10', 'Wafers', 399.0, 0, 'Pack of 10 protein wafers — Why settle for one flavor when you can have them all? The SUPERYOU Variety Box is your ultimate snack squad, loaded with: 3x Chocolate: The OG of indulgence—rich, smooth, and always hits the spot. 3x Peanut Butter: Creamy meets crunchy in this nutty masterpiece. 2x Strawberry: A nostalgic burst of berry in every bite. 2x Cheese: The sweet-salty wildcard that keeps you coming back. 10 bars, 4 bold flavors, 1 box of snack-time perfection.');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9972362019106, 'variety-pack-of-15', 'Protein Wafers - Variety Pack of 15', 'Wafers', 649.0, 0, 'Pack of 15 protein wafers — Why settle for one flavor when you can have them all? The SUPERYOU Variety Box is your ultimate snack squad, loaded with: 3x Chocolate: The OG of indulgence—rich, smooth, and always hits the spot. 3x Peanut Butter: Creamy meets crunchy in this nutty masterpiece. 6x Strawberry: A nostalgic burst of berry in every bite. 3x Cheese: The sweet-salty wildcard that keeps you coming back. Pack of 5 X 3');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9797445845282, 'chocolate-protein-powder', 'Chocolate Fermented Yeast Protein - 1Kg Jar', 'PRO', 2249.0, 0, 'Rich, dark, and ridiculously smooth . This is your classic chocolate flavor made cleaner and smarter with no added sugar , dairy or chalkiness . Each scoop is packed with 24g of gut loving protein that keeps you feeling light. Made with bio-fermented yeast protein for easy digestion and real muscle support. 28 servings per Jar');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9798393856290, 'coffee-protein-powder', 'Cold Coffee Fermented Yeast Protein - 1Kg Jar', 'PRO', 2249.0, 0, 'Love your brew? This one''s for you. A cold coffee flavour that actually tastes like a frothy coffee with no added sugar, dairy or chalkiness . Each scoop is packed with 24g of gut loving protein that keeps you feeling light. Made with bio-fermented yeast protein for easy digestion and real muscle support. 28 servings per Jar');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9655101915426, 'chocolate-choco-peanut-butter-combo-pack-of-20', 'Chocolate & Choco Peanut Butter Combo - Pack of 10 each', 'Wafers', 749.0, 0, 'Double the Chocolate, Double the Love Chocolate lovers, this one’s for you. The classic choco-peanut butter combo meets rich, smooth chocolate for the ultimate indulgent crunch. 10 x Chocolate 10 x Choco Peanut Butter Because when it comes to chocolate, more is more.');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9487398076706, 'chocolate-protein-wafer', 'Chocolate Protein Wafer - Pack of 10', 'Wafers', 449.0, 0, 'Pack of 10 protein wafers — Classic? Check. Bold? Double check. This chocolate wafer doesn’t just satisfy—it rewrites the rules. Crunchy layers wrapped in chocolate goodness, with 10g protein, 3g fiber, and no added sugar. Your favorite chocolate bar could never .');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9487397912866, 'strawberry-creme-protein-wafer', 'Strawberry Crème Protein Wafer — Pack of 10', 'Wafers', 449.0, 0, 'Pack of 10 protein wafers — Strawberry Crème brings back the good vibes with layers of crunchy wafer and creamy strawberry flavor, all powered with 10g protein, 3g fiber, and zero added sugar. Fresh, light, and a little trip down memory lane .');
INSERT INTO products (id, handle, title, product_type, price, grams, body_text) VALUES (9483316592930, 'choco-peanut-butter-protein-wafer', 'Choco Peanut Butter Protein Wafer — Pack of 10', 'Wafers', 449.0, 0, 'Pack of 10 protein wafers — Smooth chocolate meets creamy peanut butter, making every bite pure bliss. With layers of crunch and flavor wrapped in chocolate, this one’s got 10g protein, 3g fiber, and no added sugar. Go ahead, get super.');
